char *tmpl_index(Post *posts, size_t cnt) {HTMPL_StringBuilder buf = {0},l_html = {0};htmpl_sb_append_str(&l_html, "<!DOCTYPE html><head><title>me7alix' website</title><link rel=\"stylesheet\" href=\"style.css\"></head><body><div id=\"main\"><h1>Hi there, I'm Michael 👋</h1><p>Welcome to my website! I'm a coder. I love C and Go because of their simplicity. I'm exploring <a href=\"https://odin-lang.org/\">The Odin Programming Language</a>. To me, it's something between C and Go. I'm studying backend development, machine learning, and other subjects related to programming and math.</p><h2>My projects</h2><ul><li><strong><a href=\"https://github.com/me7alix/me7aLang\">me7aLang:</a></strong> A compiler for my general purpose programming language me7aLang.</li><li><strong><a href=\"https://github.com/me7alix/EpsiLang\">EpsiLang:</a></strong> An interpreted simple programming language, designed to be small and extendable.</li><li><strong><a href=\"https://github.com/me7alix/c2wasm.js\">c2wasm.js:</a></strong> <a href=\"https://me7alix.github.io/c2wasm.js/\">[DEMO]</a> A small subset of C to WASM (WAT) compiler written in JS.</li><li><strong><a href=\"https://github.com/me7alix/boot-snake\">boot-snake:</a></strong> <a href=\"https://me7alix.github.io/boot-snake/\">[DEMO]</a> A snake game written in nasm that fits into 512 bytes of bootloader and works without OS.</li><li><strong><a href=\"https://github.com/me7alix/bfos\">BFOS:</a></strong> <a href=\"https://me7alix.github.io/bfos/\">[DEMO]</a> A brainfuck interpreter written in nasm that fits into 512 bytes of bootloader and works without OS.</li><li><strong><a href=\"https://github.com/me7alix/nn.h\">nn.h:</a></strong> A simple library for creating neural networks in C.</li><li><strong><a href=\"https://github.com/me7alix/3D-renderer\">3D renderer:</a></strong> My first attempt to create a 3D renderer from scratch.</li><li><strong><a href=\"https://github.com/me7alix/voxel-engine\">Voxel engine:</a></strong> My first attempt at creating something on the OpenGL.</li><li><strong><a href=\"https://github.com/me7alix/network-game\">Network game:</a></strong> My first network game written in C using UDP sockets.</li><li><strong><a href=\"https://github.com/me7alix/bpe.odin\">BPE.odin:</a></strong> Implementation of <a href=\"https://en.wikipedia.org/wiki/Byte_pair_encoding\">byte pair encoding</a> algorithm in Odin.</li></ul><h2>Learning and Development</h2><p>I'm currently learning and improving my skills in:</p><ul><li>Advanced Golang programming</li><li>Machine Learning and AI</li><li>Low level programming in C</li></ul><h2>Github stats</h2><a href=\"https://awesome-github-stats.azurewebsites.net/index.html??cardType=level-alternate&theme=highcontrast&fontFamily=&preferLogin=false\"><img alt=\"me7alix's GitHub Stats\" src=\"https://awesome-github-stats.azurewebsites.net/user-stats/me7alix?cardType=level-alternate&theme=highcontrast&fontFamily=&preferLogin=false\" /></a><h2>Blog posts</h2>"); {for (int i = cnt - 1; i >= 0; i--) {HTML("<div><h3>%s</h3>%s</div>",posts[i].title,posts[i].html);if (i != 0) {HTML("<br/>");}}if (cnt == 0) {HTML("<h3>There are no posts here yet</h3>");}}htmpl_sb_append_str(&l_html, "<p><br />Thanks for stopping by! Have a great day! 😊</p></div></body></html>");htmpl_sb_destroy(&buf);return l_html.str;}char *tmpl_admin(Post *posts, size_t cnt) {HTMPL_StringBuilder buf = {0},l_html = {0};htmpl_sb_append_str(&l_html, "<!DOCTYPE html><head><title>me7alix' website</title><link rel=\"stylesheet\" href=\"style.css\"></head><body><script>function postSend() {let title = document.getElementById('title').value;let html = document.getElementById('html').value;fetch('/post', {method: 'POST',headers: { 'Content-Type': 'text/plain' },body: title+'\\n'+html}).then(resp => { location.reload() });}function postRemove(id) {fetch('/post/'+id, {method: 'DELETE'}).then(resp => { location.reload() });}</script><div id=\"main\"><h2>Blog posts</h2>"); {for (size_t i = 0; i < cnt; i++) {HTML("<div><h3>%s</h3>%s<button onclick=\"postRemove('%d')\">Remove</button></div>", posts[i].title, posts[i].html, posts[i].id);}if (cnt == 0) {HTML("<h3>There are no posts here yet</h3>");}}htmpl_sb_append_str(&l_html, "<h2>New post</h2><p>Title</p><input id=\"title\" type=\"text\" /><p>Body</p><textarea id=\"html\"></textarea><br/><button onclick=\"postSend()\">Add</button></div></body></html>");htmpl_sb_destroy(&buf);return l_html.str;}